import {getSpecies} from './data.js';
import {drawAsset,monsterAssetKey,assetStatus} from './assets.js';
// Pending or failed assets never display the retired monster design.
export function drawMonster(ctx,id,x,y,size=64,t=0,back=false){
 const key=monsterAssetKey(id);if(drawAsset(ctx,key,x,y,size))return true;
 ctx.save();ctx.fillStyle=assetStatus(key)==='failed'?'#ad8060':'#789b93';
 const dot=Math.max(2,Math.round(size/24));
 for(let i=0;i<3;i++)ctx.fillRect(Math.round(x+size/2+(i-1)*dot*3-dot/2),Math.round(y+size/2),dot,dot);
 ctx.restore();return false;
}
export function drawMonsterDefault(ctx,id,x,y,size=64,t=0,back=false){const m=getSpecies(id),u=size/32;ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(u,u);if(back){ctx.translate(32,0);ctx.scale(-1,1);}const body=m.color,outline='#344d50',light='#f8f3d9',dark='#50737b',gold='#e5c87e';const r=(a,b,c,d,col)=>{ctx.fillStyle=col;ctx.fillRect(a,b,c,d)};const box=(a,b,c,d,col)=>{r(a,b,c,d,outline);r(a+1,b+1,c-2,d-2,col)};const eye=(a,b)=>{r(a,b,3,4,outline);r(a,b,1,1,'#fff9e2')};const bob=Math.sin(t*3+m.id)*.5;ctx.translate(0,Math.round(bob));const st=m.stage;r(8,28,18,2,'#315e4230');
switch(m.shape){
case 'bird':case 'raptor':{box(10,12,13,13,body);box(15,6,10,12,body);r(14,10,2,7,body);r(12,17,9,6,light);box(5,15,10,7,m.shape==='raptor'?'#7e6f60':'#a1b1b1');r(3,17,4,3,outline);r(23,13,6,3,gold);eye(20,10);r(12,25,3,3,gold);r(19,25,3,3,gold);r(11,28,5,1,outline);r(18,28,5,1,outline);if(st>1){r(5,13,3,3,light);r(2,11,3,5,outline);r(17,4,3,3,gold);}if(st>2){r(14,2,4,4,outline);r(15,2,2,3,gold);r(1,9,2,3,light);r(1,21,4,2,light);}if(m.name==='괭이갈매기'){r(5,19,5,2,'#57767b');r(25,14,2,1,'#c07868');}break;}
case 'fish':case 'goby':{box(8,10,18,15,body);r(5,13,5,10,body);r(25,13,3,9,body);box(2,12,6,13,body);r(1,10,2,5,outline);r(1,23,2,4,outline);r(10,25,11,2,outline);r(12,7,9,3,outline);r(13,8,7,3,body);r(10,20,10,3,'#f0dcba');eye(22,13);r(25,20,3,1,outline);r(13,15,3,5,'#fff2c780');if(m.motif==='혹돔'){box(20,6,7,9,body);eye(23,14);}if(m.motif==='돌돔'){for(let i=10;i<22;i+=4)r(i,11,2,13,'#516d79');eye(23,13);}if(st>1){r(11,5,4,3,gold);r(15,4,4,4,gold);}if(st>2){r(8,3,3,4,outline);r(12,1,3,6,outline);r(16,2,3,5,outline);r(13,2,1,3,gold);}if(m.shape==='goby'){r(7,22,3,5,body);r(21,22,3,5,body);r(12,13,2,2,dark);r(16,19,2,2,dark);}break;}
case 'octopus':{for(let i=0;i<4;i++){box(4+i*6,19,5,9,body);r(4+i*6,27,7,2,body);}box(8,6,17,17,body);r(12,3,9,3,body);r(11,9,4,3,'#ffffff50');eye(12,14);eye(21,14);r(17,20,3,2,dark);if(st>1)r(12,5,11,2,gold);if(st>2){r(13,1,3,4,gold);r(20,1,3,4,gold);r(16,2,4,4,gold);}break;}
case 'squid':{box(10,8,13,15,body);r(13,4,7,4,body);r(15,1,3,3,outline);r(6,12,4,9,body);r(23,12,4,9,body);for(let i=0;i<4;i++)box(9+i*4,21,3,8,body);eye(12,16);eye(20,16);if(st>1)r(13,10,7,2,gold);if(st>2){r(4,11,2,7,gold);r(27,11,2,7,gold);}break;}
case 'shell':{box(4,11,25,15,body);r(7,7,19,5,body);r(11,5,11,3,outline);for(let i=8;i<27;i+=5)r(i,10,2,11,'#ffffff60');r(5,23,23,3,outline);r(10,24,15,3,light);eye(12,20);eye(22,20);if(st>1)r(12,7,8,3,gold);if(st>2){r(14,3,5,3,gold);r(2,15,2,7,gold);r(29,15,2,7,gold);}break;}
case 'urchin':{for(let i=0;i<8;i++){ctx.save();ctx.translate(16,17);ctx.rotate(i*Math.PI/4);r(-1,-15,3,9,outline);r(0,-14,1,7,body);ctx.restore();}box(7,8,19,19,body);r(11,5,11,3,body);eye(11,15);eye(21,15);r(16,22,3,1,outline);if(st>1)r(13,9,7,2,gold);if(st>2){r(11,3,3,4,gold);r(19,3,3,4,gold);}break;}
case 'slug':{box(4,16,24,12,body);box(17,10,11,12,body);r(18,6,3,5,outline);r(25,5,3,6,outline);r(19,6,1,4,body);r(26,5,1,5,body);eye(22,14);r(6,19,2,3,dark);r(11,23,2,2,dark);r(14,18,2,2,dark);if(st>1){r(5,13,4,3,gold);r(10,13,4,3,gold);}if(st>2){r(8,10,3,4,gold);r(13,11,3,4,gold);}break;}
case 'shrimp':{box(7,12,18,11,body);box(18,8,10,11,body);eye(24,10);r(24,7,2,2,outline);r(22,4,4,1,outline);r(17,2,7,1,outline);for(let i=8;i<21;i+=4){r(i,14,1,9,light);r(i,23,1,5,outline);}box(2,18,6,7,body);r(1,25,6,2,body);if(st>1)r(12,10,5,2,gold);if(st>2){r(20,5,3,4,gold);r(15,7,3,4,gold);}break;}
case 'flower':{box(14,16,5,12,'#81a373');box(5,21,10,5,'#88af78');box(18,23,9,5,'#88af78');const petal=m.color;box(8,7,17,14,petal);box(12,3,8,22,petal);box(4,11,24,7,petal);box(10,10,13,10,gold);eye(12,12);eye(19,12);r(15,18,3,1,outline);if(st>1){r(7,6,4,3,light);r(23,10,3,3,light);}if(st>2){r(1,7,3,4,gold);r(27,20,3,3,gold);r(14,0,4,3,light);}break;}
case 'plant':case 'kelp':{box(12,13,10,15,body);for(let i=0;i<3;i++){box(4+i*7,7+(i%2)*4,7,12,body);}r(5,5,3,3,body);r(13,4,3,9,body);r(22,5,3,7,body);r(13,25,9,3,dark);eye(12,17);eye(20,17);if(m.shape==='kelp'){r(7,20,3,6,body);r(25,16,3,7,body);}else{r(10,25,3,5,dark);r(20,25,3,5,dark);}if(st>1){r(13,5,4,3,gold);r(5,9,3,2,light);}if(st>2){r(11,1,8,3,gold);r(3,2,3,4,body);r(25,1,3,5,body);}break;}
case 'dragonfly':{box(14,8,6,21,body);box(12,5,10,8,body);box(2,11,12,6,'#d7e9d7');box(20,11,11,6,'#d7e9d7');box(4,19,10,4,'#c4dcd5');box(20,19,9,4,'#c4dcd5');eye(12,7);eye(20,7);r(15,14,4,1,outline);r(15,19,4,1,outline);if(st>1){r(3,12,8,1,gold);r(22,12,7,1,gold);}if(st>2)r(15,2,5,4,gold);break;}
case 'beetle':{for(let i=0;i<3;i++){r(3,12+i*5,5,2,outline);r(24,12+i*5,5,2,outline);}box(7,10,19,17,body);box(11,5,11,9,outline);r(12,2,2,4,outline);r(20,2,2,4,outline);eye(12,7);eye(19,7);r(16,13,1,13,outline);for(let i=0;i<3;i++){r(10,14+i*4,3,2,outline);r(21,14+i*4,2,2,outline);}if(st>1)r(11,10,11,2,gold);if(st>2)r(13,1,7,3,gold);break;}
case 'crab':{box(8,12,16,13,body);for(let i=0;i<3;i++){r(3,16+i*4,6,2,outline);r(23,16+i*4,6,2,outline);}box(1,7,7,9,body);box(24,7,7,9,body);r(3,5,2,5,body);r(27,5,2,5,body);eye(11,10);eye(19,10);r(14,21,4,1,outline);break;}
case 'starfish':{const points=[[14,2,5,25],[4,12,25,5],[7,8,5,16],[21,8,5,16],[4,24,8,4],[22,24,8,4]];for(const [a,b,w,h] of points)box(a,b,w,h,body);box(10,11,13,12,body);eye(12,14);eye(20,14);break;}
case 'coral':case 'anemone':{for(let i=0;i<5;i++){const a=4+i*5;box(a,5+(i%2)*4,4,20-(i%2)*4,body);if(m.shape==='coral'){r(a-2,11,3,3,body);r(a+3,15,3,3,body);}}box(8,19,19,9,body);eye(12,21);eye(21,21);r(9,27,19,2,outline);break;}
case 'seal':{box(9,12,15,14,body);box(12,5,14,12,body);r(14,2,9,4,body);box(3,18,8,6,body);box(21,18,9,6,body);r(8,26,7,3,body);r(20,26,8,3,body);r(13,17,8,7,'#d1ded5');eye(15,8);eye(23,8);r(19,13,3,2,outline);r(12,14,5,1,light);r(24,14,6,1,light);r(11,16,5,1,light);r(24,16,6,1,light);r(14,0,3,3,gold);r(22,0,3,3,gold);r(17,1,5,2,gold);for(let i=0;i<3;i++){r(1+i*10,29,7,1,'#b6dfdc');}break;}}
ctx.restore();}
// v0.40 그림이 바라보는 쪽. 뒷모습 그림은 쓰지 않고, 앞모습 그림을 좌우로 뒤집어 방향을 맞춰요.
//   결투에서 내 우산몬은 오른쪽(상대 쪽), 상대 우산몬은 왼쪽(내 쪽)을 봐요.
//   FACES_RIGHT: 오른쪽을 보는 그림 · FACES_FRONT: 정면 그림(뒤집지 않아요) · 나머지: 왼쪽을 보는 그림
//   그림을 새로 바꾸면 여기 번호를 맞춰 주세요.
export const FACES_RIGHT=new Set([]);
export const FACES_FRONT=new Set([1,2,4,5,6,7,9,10,12,13,14,15,19]);
export const facing=id=>FACES_RIGHT.has(Number(id))?'right':FACES_FRONT.has(Number(id))?'front':'left';
export function portrait(canvas,id,t=0,back=false,mirror=false){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.imageSmoothingEnabled=false;ctx.save();if(mirror){ctx.translate(canvas.width,0);ctx.scale(-1,1);}drawMonster(ctx,id,0,0,canvas.width,t,back);ctx.restore();}
// Battle: the foe looks left (toward me), my 우산몬 looks right (toward the foe). Both use the front picture.
export function battlePortrait(canvas,id,mine=false){const f=facing(id);portrait(canvas,id,0,false,mine?f==='left':f==='right');}
export function drawHuman(ctx,x,y,color='#3a7e89',dir='down',step=0,kind='normal',assetKey=null,size=32){if(!assetKey||!drawAsset(ctx,assetKey,x,y,size)){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(size/32,size/32);drawHumanDefault(ctx,0,0,color,dir,step,kind);ctx.restore();}}
export function drawHumanDefault(ctx,x,y,color='#3a7e89',dir='down',step=0,kind='normal'){const r=(a,b,w,h,c)=>{ctx.fillStyle=c;ctx.fillRect(Math.round(x+a),Math.round(y+b),w,h)};r(5,28,22,4,'#243b3d30');r(9,22,6,8,'#3f5964');r(18,22,5,8,'#3f5964');r(7,29-(step%2),8,3,'#273e46');r(17,29+(step%2),8,3,'#273e46');r(7,14,18,12,color);r(4,16,4,8,'#e2b68a');r(25,16,4,8,'#e2b68a');r(9,4,15,13,'#e6c19a');r(7,1,19,7,'#374f4d');r(9,0,14,3,kind==='history'?'#46586b':'#ddbc73');r(6,5,21,3,kind==='history'?'#46586b':'#e5cf91');if(dir!=='up'){r(dir==='left'?10:dir==='right'?21:12,10,2,3,'#28444a');if(dir==='down')r(20,10,2,3,'#28444a');r(16,15,3,1,'#bd8b77');}else{r(9,7,15,5,'#374f4d');r(10,17,13,10,'#ba8b57');r(13,20,7,5,'#d4b477');}if(kind==='history'){r(11,17,3,9,'#ece7cb');r(21,17,3,9,'#ece7cb');r(9,0,15,3,'#354754');}if(kind==='enemy'){r(9,4,15,4,'#d9dfd7');r(11,17,11,2,'#d8ddd4');}}
